    private void addSettingCheck(String title,String detail,boolean checked,String key,boolean refresh){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(7),dp(8),dp(7));surface(row);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(6);content.addView(row,p);LinearLayout labels=new LinearLayout(this);labels.setOrientation(1);labels.addView(text(title,compact?13:14,white));TextView sub=text(detail,compact?10:11,muted);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(2);labels.addView(sub,sp);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));CheckBox check=new CheckBox(this);if(Build.VERSION.SDK_INT>=21)check.setButtonTintList(android.content.res.ColorStateList.valueOf(green));check.setChecked(checked);row.addView(check);View.OnClickListener toggle=v->check.setChecked(!check.isChecked());row.setOnClickListener(toggle);check.setOnCheckedChangeListener((button,isChecked)->{getPreferences(0).edit().putBoolean(key,isChecked).apply();if("forceSkeuomorphic".equals(key)){forceSkeuomorphic=isChecked;applyAppearance();}else if("compactUi".equals(key)){compact=isChecked;applyAppearance();}else if("keepScreenOn".equals(key)){if(isChecked)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}else if("showSecurityLabel".equals(key)){build();showSettingsPanel();}});}
