    private void applyAppearance(){boolean narrowScreen=getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density<=320;compact=getPreferences(0).getBoolean("compactUi",narrowScreen);bg=modern?Color.rgb(250,250,250):(forceSkeuomorphic?Color.rgb(38,38,38):Color.rgb(245,245,245));panel=modern?Color.WHITE:(forceSkeuomorphic?Color.rgb(57,57,57):Color.WHITE);green=material2015?Color.rgb(33,150,243):(modern?Color.rgb(63,114,155):(forceSkeuomorphic?Color.rgb(255,179,71):Color.rgb(63,114,155)));white=(modern||!forceSkeuomorphic)?Color.rgb(38,38,38):Color.WHITE;muted=(modern||!forceSkeuomorphic)?Color.rgb(117,117,117):Color.rgb(205,205,205);lineColor=(modern||!forceSkeuomorphic)?Color.rgb(230,230,230):Color.rgb(20,20,20);if(Build.VERSION.SDK_INT>=21){getWindow().setStatusBarColor(material2015?Color.rgb(25,118,210):((modern||!forceSkeuomorphic)?Color.rgb(245,245,245):Color.rgb(31,31,31)));getWindow().setNavigationBarColor(material2015?Color.BLACK:((modern||!forceSkeuomorphic)?Color.WHITE:Color.rgb(31,31,31)));}build();showSettingsPanel();}
    interface ItemsReady{void done(ArrayList<Item> list);}
    private void request(String method,String[][] args,String tag,ItemsReady done){if(user.isEmpty()){showSettings();return;}final int seq=++requestId;status.setText("Connecting to "+server);AsyncTask<Void,Void,Object> task=new AsyncTask<Void,Void,Object>(){protected Object doInBackground(Void...v){try{HttpURLConnection c=(HttpURLConnection)new URL(apiUrl(method,args)).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","EpicStreaming/1.0 Android");InputStream in=c.getInputStream();Document d=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(in);in.close();Element response=d.getDocumentElement();if(response!=null&&!"ok".equals(response.getAttribute("status"))){NodeList errors=response.getElementsByTagName("error");throw new Exception(errors.getLength()>0?((Element)errors.item(0)).getAttribute("message"):"Server rejected the request");}ArrayList<Item> out=new ArrayList<>();NodeList nodes=d.getElementsByTagName(tag);for(int i=0;i<nodes.getLength();i++){Element e=(Element)nodes.item(i);if(!e.hasAttribute("id"))continue;Item item=new Item(e.getAttribute("id"),attr(e,"name",attr(e,"title","Unknown")),attr(e,"artist",""),attr(e,"coverArt",""));item.album=attr(e,"album","");item.durationMs=parseDurationMs(e);out.add(item);}return out;}catch(Exception e){return e;}}protected void onPostExecute(Object result){if(seq!=requestId)return;if(result instanceof Exception){status.setText("Could not load library");content.removeAllViews();addMessage(((Exception)result).getMessage()+"\nCheck server, Wi-Fi, and login in Settings.");}else{status.setText(server);done.done((ArrayList<Item>)result);}}};if(Build.VERSION.SDK_INT>=11)task.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);else task.execute();}
    private String attr(Element e,String k,String f){String v=e.getAttribute(k);return v.length()==0?f:v;}
    private int parseDurationMs(Element e){try{return (int)(Double.parseDouble(e.getAttribute("duration"))*1000);}catch(Exception ignored){return 0;}}
    private void showItems(ArrayList<Item> items,String empty){content.removeAllViews();if(items.size()==0){addMessage(empty);return;}for(Item item:items){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(10),dp(9),dp(13),dp(9));surface(row);int artSize=compact?dp(50):dp(70);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,artSize+dp(20));rp.bottomMargin=dp(compact?8:11);content.addView(row,rp);ImageView cover=new ImageView(this);GradientDrawable artBg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(79,149,194),Color.rgb(25,65,101)});artBg.setCornerRadius(dp(material2015?5:8));cover.setBackgroundDrawable(artBg);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);row.addView(cover,new LinearLayout.LayoutParams(artSize,artSize));if(!item.cover.isEmpty()&&getPreferences(0).getBoolean("loadArtwork",true))loadCover(item.cover,cover);LinearLayout labels=new LinearLayout(this);labels.setOrientation(1);labels.setGravity(Gravity.CENTER_VERTICAL);labels.setPadding(dp(compact?11:15),0,dp(4),0);TextView title=text(item.name,compact?13:16,white);title.setTypeface(null,Typeface.BOLD);title.setSingleLine(true);TextView sub=text(item.artist.isEmpty()?(currentTab.equals("Artists")?"Artist":"Open to browse"):item.artist,compact?10:12,muted);sub.setSingleLine(true);labels.addView(title);LinearLayout.LayoutParams subParams=new LinearLayout.LayoutParams(-1,-2);subParams.topMargin=dp(4);labels.addView(sub,subParams);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));TextView affordance=text(currentTab.equals("Songs")?"▶":"›",compact?18:22,green);affordance.setGravity(Gravity.CENTER);row.addView(affordance,new LinearLayout.LayoutParams(dp(28),dp(40)));row.setContentDescription(item.name+(item.artist.length()==0?"":" by "+item.artist));row.setOnClickListener(v->{if(currentTab.equals("Artists"))openArtist(item);else if(currentTab.equals("Albums"))openAlbum(item);else playSong(item);});}}
    private void addMessage(String s){TextView t=text(s,14,muted);t.setPadding(dp(12),dp(20),dp(12),dp(20));content.addView(t);}
    private void openAlbum(Item a){content.removeAllViews();addMessage("Loading album…");request("getAlbum",new String[][]{{"id",a.id}},"song",items->{content.removeAllViews();addHeading(a.name+(a.artist.isEmpty()?"":"\n"+a.artist));for(Item i:items){i.cover=a.cover;i.album=a.name;addSongRow(i);}});}
    private void openArtist(Item a){content.removeAllViews();addMessage("Loading artist…");request("getArtist",new String[][]{{"id",a.id}},"album",items->{content.removeAllViews();addHeading(a.name);for(Item i:items){if(i.artist.isEmpty())i.artist=a.name;addAlbumRow(i);}});}
